#!/usr/bin/env python3
"""Render the human-readable views of the knowledge-redesign package from its
canonical JSON. DESIGN-PACKAGE TOOLING ONLY. Every file this writes carries a
"generated - do not edit" header; edit the JSON and re-run.

Usage: python3 -I tools/render.py
"""
import sys
from collections import Counter, defaultdict
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import kr_lib as kr  # noqa: E402

GEN = "_Generated by `tools/render.py` from the canonical JSON — do not edit by hand._"
BRANCH_TITLE = {"trunk": "Main technology tree (trunk)", "military": "1.1 Military", "medicine": "1.2 Medicine",
                "engineering": "1.3 Engineering", "natural_science": "1.4 Natural Science",
                "agriculture": "1.5 Agriculture"}

DEFAULTS = {
    "missingInputs": lambda c: ("No physical input: the knowledge is held polity-wide once complete."
                                if not any((c.get("inputs") or {}).values()) else
                                "Eligible but not realizable where an input is absent; the blocked action names it."),
    "unknownResource": lambda c: ("n/a" if not (c.get("inputs") or {}).get("resources") else
                                  "Knowledge only: no deposit is identified or targeted until the polity has located "
                                  "and identified it."),
    "aiValuation": lambda c: "Valued through the goal closures and consumers it unlocks; never from unknown cells.",
    "playerCommunication": lambda c: "Research panel shows what it makes eligible and which system realizes it; "
                                     "locked actions name the missing prerequisite.",
}


def esc(x):
    if x is None:
        return "—"
    s = str(x).replace("|", "/").replace("\n", " ")
    return s if s.strip() else "—"


def cap_field(c, k):
    v = (c or {}).get(k)
    if v in (None, "", "default"):
        return DEFAULTS[k](c or {}) if k in DEFAULTS else "—"
    return v


def cost_cell(n):
    if n.get("oldCost") is None:
        return f"{n['cost']:,.0f} (new)"
    if abs((n.get("oldCost") or 0) - (n.get("cost") or 0)) < 0.5:
        return f"{n['cost']:,.0f}"
    return f"{n['oldCost']:,.0f} → {n['cost']:,.0f}"


def grants_cell(c, limit=6):
    g = (c or {}).get("grants") or []
    return esc("; ".join(g[:limit]) + (f" (+{len(g) - limit})" if len(g) > limit else "")) if g else "—"


def write(path, lines):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def load():
    tech = kr.load_json(kr.PKG / "technology-tree-proposal.json")
    civ = kr.load_json(kr.PKG / "civics-tree-proposal.json")
    inv = kr.load_json(kr.DATA / "current-tree-inventory.json")
    corpus = {}
    for f in sorted((kr.PKG / "corpus").glob("*.json")):
        if f.name == "index.json":
            continue
        for e in kr.load_json(f):
            corpus[e["id"]] = dict(e, _file=f.name)
    reg_path = kr.PKG / "sources" / "register.json"
    reg = {s["id"]: s for s in kr.load_json(reg_path)} if reg_path.exists() else {}
    return tech, civ, inv, corpus, reg


def render_current_audit(tech, civ, inv):
    prop = {n["id"]: n for n in tech["nodes"] + civ["nodes"]}
    by_branch = defaultdict(list)
    for n in inv["nodes"]:
        by_branch[("civics" if n["tree"] == "civics" else n["branch"])].append(n)
    files = []
    for br in kr.BRANCHES + ["civics"]:
        rows = sorted(by_branch.get(br, []), key=lambda n: n["key"])
        if not rows:
            continue
        name = f"audit/current-tree-inventory-{br}.md"
        files.append((br, name, len(rows)))
        L = [f"# Current-tree inventory — {BRANCH_TITLE.get(br, 'Civics (Tree 2)')}", "", GEN, "",
             "MEASURED from `Sim.Data/content/research.json` at the baseline head (`data/current-tree-inventory.json`). "
             "Disposition, changes and compatibility columns are PROPOSED (from the canonical proposal files).", "",
             "| key | id | name | Age | cost (mag) | prerequisites | consumers / unlocks | dependants | existing description | disposition | changes & rationale | compatibility risk |",
             "|---|---|---|---|---|---|---|---|---|---|---|---|"]
        for n in rows:
            p = prop.get(n["id"], {})
            cons = []
            cons += n.get("entityConsumers") or []
            if n.get("researchStageAtom"):
                cons.append("research stage")
            if n.get("taxGateAtom"):
                cons.append("tax edict")
            cons += [f"Age {m['milestone']} ({m['role']})" for m in n.get("ageMilestones") or []]
            ua = (n.get("unlockAudit") or {}).get("class")
            compat = p.get("compatibility") or {}
            compat_s = "; ".join(f"{k}: {v}" for k, v in compat.items() if v) if compat else "none (unchanged)"
            L.append("| " + " | ".join([
                str(n["key"]), f"`{n['id']}`", esc(n["name"]), n["age"], f"{n['cost']:,.0f} ({n['magnitude']})",
                esc(n.get("prereq")), esc(("class " + ua + "; " if ua else "") + "; ".join(cons)),
                esc(", ".join(n.get("dependants") or [])) if n.get("dependants") else "—",
                esc(n.get("desc")), esc(", ".join(p.get("disposition") or ["?"])),
                esc((p.get("changes") or "") + (" — " + p["rationale"] if p.get("rationale") else "")),
                esc(compat_s)]) + " |")
        write(kr.PKG / name, L)
    return files


def render_proposal(tech, civ, corpus):
    files = []
    nodes = [n for n in tech["nodes"]]
    by_branch = defaultdict(list)
    for n in nodes:
        by_branch[n["branch"]].append(n)
    for br in kr.BRANCHES:
        rows = sorted(by_branch.get(br, []), key=lambda n: (kr.AGES.index(n["age"]) if n["age"] in kr.AGES else 99, n["key"]))
        name = f"proposal/technology-{br}.md"
        files.append((br, name, len(rows)))
        L = [f"# Proposed technology graph — {BRANCH_TITLE[br]}", "", GEN, "",
             "PROPOSED. `status`: existing / new / retired. Cost in Research Points (BaseCost = 92.4 × 2^magnitude). "
             "Ordered by Age, then key.", ""]
        for age in kr.AGES:
            arow = [n for n in rows if n["age"] == age]
            if not arow:
                continue
            L += [f"## {age} — {len(arow)} node(s)", "",
                  "| key | id | name | status / disposition | kind | cost | prerequisites | grants (capability) | owner · milestone | why / rationale |",
                  "|---|---|---|---|---|---|---|---|---|---|"]
            for n in arow:
                c = n.get("capability") or {}
                why = n.get("whyDistinct") or n.get("rationale") or n.get("retireReason") or ""
                L.append("| " + " | ".join([
                    str(n["key"]), f"`{n['id']}`", esc(n["name"]),
                    esc(n["status"] + " / " + ", ".join(n.get("disposition") or [])), esc(n.get("nodeKind")),
                    cost_cell(n), esc(n.get("prereq")), grants_cell(c),
                    esc(f"{c.get('realizationOwner', '—')} · {c.get('milestone', '—')} ({c.get('status', '—')})"),
                    esc(why)]) + " |")
            L.append("")
        write(kr.PKG / name, L)
    return files


def render_matrix(tech, civ):
    files = []
    allnodes = [n for n in tech["nodes"] + civ["nodes"] if n["status"] != "retired"]
    groups = defaultdict(list)
    for n in allnodes:
        groups["civics" if n["tree"] == "civics" else n["branch"]].append(n)
    for br in kr.BRANCHES + ["civics"]:
        rows = sorted(groups.get(br, []), key=lambda n: n["key"])
        name = f"matrix/capability-matrix-{br}.md"
        files.append((br, name, len(rows)))
        L = [f"# Capability–dependency matrix — {BRANCH_TITLE.get(br, 'Civics (Tree 2)')}", "", GEN, "",
             "PROPOSED. One row per active node. `default` texts are the package-wide defaults stated in "
             "`capability-dependency-matrix.md` §2.", "",
             "| key | id | prerequisites | capability grants | inputs (resources · geography · infrastructure · institutions) | downstream consumers | realization owner | milestone · status | AI valuation | missing inputs | unknown resource | player communication | acceptance test | migration |",
             "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
        for n in rows:
            c = n.get("capability") or {}
            inp = c.get("inputs") or {}
            inp_s = " · ".join(", ".join(inp.get(k) or []) or "—" for k in ("resources", "geography", "infrastructure", "institutions"))
            deps = (n.get("derived") or {}).get("dependants") or []
            compat = n.get("compatibility") or {}
            mig = "; ".join(f"{k}: {v}" for k, v in compat.items() if v) if compat else (
                "new key; no saved state" if n["status"] == "new" else "unchanged")
            L.append("| " + " | ".join([
                str(n["key"]), f"`{n['id']}`", esc(n.get("prereq")), grants_cell(c, 8), esc(inp_s),
                esc(", ".join(deps[:8]) + (f" (+{len(deps) - 8})" if len(deps) > 8 else "")) if deps else "—",
                esc(c.get("realizationOwner")), esc(f"{c.get('milestone')} · {c.get('status')}"),
                esc(cap_field(c, "aiValuation")), esc(cap_field(c, "missingInputs")),
                esc(cap_field(c, "unknownResource")), esc(cap_field(c, "playerCommunication")),
                esc(n.get("acceptanceTest") or "covered by the lane's packet acceptance (roadmap)"), esc(mig)]) + " |")
        write(kr.PKG / name, L)
    return files


def render_civics(civ):
    nodes = sorted(civ["nodes"], key=lambda n: (kr.AGES.index(n["age"]) if n["age"] in kr.AGES else 99, n["key"]))
    L = ["# Proposed civics graph — generated detail", "", GEN, "",
         "PROPOSED. Costs are stated in points of the civics pool: Civics Points if D-061 is ratified, otherwise Research "
         "Points from the shared pool. States: Unresearched → Researched/Available → Adopted → Active → Realized.", ""]
    for n in nodes:
        c = n.get("civic") or {}
        cap = n.get("capability") or {}
        L += [f"### {n['key']} · `{n['id']}` — {n['name']}", "",
              f"- **Status / disposition:** {n['status']} / {', '.join(n.get('disposition') or [])} · **category:** "
              f"{c.get('category', '—')} · **Age relation:** {n['age']} ({esc(c.get('ageRelation'))}) · **cost:** {cost_cell(n)}",
              f"- **Prerequisites:** {esc(n.get('prereq'))}",
              f"- **Concept:** {esc(c.get('concept'))}",
              f"- **Eligibility it creates:** {esc(c.get('eligibility'))}",
              f"- **Current effect:** {esc(c.get('currentEffect') or cap.get('currentEffect'))} · **deferred effect:** {esc(c.get('deferredEffect') or cap.get('deferredEffect'))}",
              f"- **Owner system · milestone:** {esc(c.get('ownerSystem') or cap.get('realizationOwner'))} · {esc(c.get('milestone') or cap.get('milestone'))}",
              f"- **States:** {esc(c.get('states'))}",
              f"- **Technology links:** {esc(c.get('techLinks'))} · **institution links:** {esc(c.get('institutionLinks'))}",
              f"- **AI valuation:** {esc(c.get('aiValuation') or cap.get('aiValuation'))} · **required for progression:** {esc(c.get('required'))}",
              f"- **Rationale:** {esc(n.get('rationale') or n.get('whyDistinct'))}", ""]
    write(kr.PKG / "proposal" / "civics-detail.md", L)


def _tbl(rows, cols, heads=None):
    heads = heads or cols
    out = ["| " + " | ".join(heads) + " |", "|" + "---|" * len(heads)]
    for r in rows:
        out.append("| " + " | ".join(esc(r.get(c) if not isinstance(r.get(c), list) else "; ".join(map(str, r.get(c))))
                                      for c in cols) + " |")
    return out


def render_civics_overview(civ):
    m = civ.get("civicsMeta") or {}
    nodes = [n for n in civ["nodes"] if n["status"] != "retired"]
    by_id = {n["id"]: n for n in nodes}
    L = ["# Civics tree proposal (Tree 2)", "", GEN, "",
         "**Status: " + esc(m.get("status") or "PROPOSED") + "**", "",
         f"Cost unit: **{esc(m.get('costUnit'))}** — {esc(m.get('costUnitNote'))} Per-civic detail: "
         "`proposal/civics-detail.md`; capability matrix: `matrix/capability-matrix-civics.md`; design notes: "
         "`research/lane-notes/D12-civics.md`; canonical data: `civics-tree-proposal.json`.", ""]
    c = m.get("counts") or {}
    L += ["## 1. Summary", "",
          f"- Existing civics: {c.get('existingCivics')} (kept {c.get('existingKept')}, changed {c.get('existingChanged')}); "
          f"new micro-civics {c.get('newMicro')}; new macro-civics (regime forms) {c.get('newMacro')}; total {len(nodes)}.",
          f"- New civics total cost: {c.get('newCivicsTotalCost'):,.0f} points." if c.get('newCivicsTotalCost') else "",
          "- By strand: " + ", ".join(f"{k} {v}" for k, v in (c.get("byStrand") or {}).items()),
          "- By primary milestone: " + ", ".join(f"{k} {v}" for k, v in (c.get("byPrimaryMilestone") or {}).items()),
          "- By progression role: " + ", ".join(f"{k} {v}" for k, v in (c.get("byProgressionRole") or {}).items()), ""]
    L += ["## 2. Design rules", ""] + [f"- {r}" for r in m.get("designRules") or []] + [""]
    L += ["## 3. Strands", ""] + _tbl(m.get("strands") or [], ["id", "name", "scope", "existing", "new"]) + [""]
    L += ["## 4. Gate audit — every civic gate today", ""] + \
        _tbl(m.get("gateAudit") or [], ["id", "gate", "current", "civicAtoms", "classification", "evidence", "recommendation"]) + [""]
    so = m.get("stageAtomOptions") or {}
    L += ["## 5. The research-stage civic atom", "", f"**Question.** {esc(so.get('question'))}", "",
          f"**Measured baseline.** {esc(so.get('measuredBaseline'))}", ""]
    for o in so.get("options") or []:
        L += [f"- **Option {o.get('id')} — {esc(o.get('name'))}.** {esc(o.get('change'))} Pros: {esc('; '.join(o.get('pros') or []))}. "
              f"Cons: {esc('; '.join(o.get('cons') or []))}." + (f" Risk: {esc(o.get('risk'))}." if o.get('risk') else "")]
    L += ["", f"**Recommendation.** {esc(so.get('recommendation'))}", ""]
    tol = m.get("cpPacingTolerances") or {}
    L += ["## 6. Civics Points pacing tolerances (PROPOSED)", "", f"{esc(tol.get('status'))}. {esc(tol.get('nature'))}", "",
          f"Protocol: {esc(tol.get('protocol'))}", ""] + _tbl(tol.get("tolerances") or [], ["id", "kind", "rule"]) + [""]
    cb = m.get("costBalance") or {}
    L += ["## 7. Costs — micro/macro balance", "", f"Rule: {esc(cb.get('rule'))}", ""] + \
        [f"- {j}" for j in cb.get("justification") or []] + ["", f"Measured: {esc(cb.get('measuredResult'))}", ""]
    rows = []
    for r in cb.get("table") or []:
        rows.append({"Age": r.get("age"), "micro n": r.get("microCount"),
                     "micro magnitude (min/med/max)": "/".join(str((r.get("microMagnitude") or {}).get(k)) for k in ("min", "median", "max")),
                     "micro median cost": r.get("microCostMedian"), "macro n": r.get("macroCount"),
                     "macro magnitude (min/med/max)": "/".join(str((r.get("macroMagnitude") or {}).get(k)) for k in ("min", "median", "max")),
                     "macro median cost": r.get("macroCostMedian"), "premium (median)": r.get("premiumOverMicroMedian")})
    if rows:
        L += _tbl(rows, list(rows[0].keys())) + [""]
    wl = (m.get("workloadByAge") or {}).get("rows") or []
    if wl:
        L += ["If D-061 is NOT ratified the new civics compete with technology for the one RP pool:", ""] + \
            _tbl(wl, ["age", "technologyCost", "existingCivicsCost", "newCivicsCost", "newCivicsAsShareOfTechnology"]) + [""]
    macros = sorted([n for n in nodes if (n.get("civic") or {}).get("category") == "macro"],
                    key=lambda n: (kr.AGES.index(n["age"]), n["key"]))
    L += ["## 8. Macro-civics (regime forms)", "",
          "Leaves (nothing requires a form; no form requires a form), never Age CORE facts, eligibility only in M6; "
          "adoption and active effects are M8 (D-D).", ""]
    L += ["| key | id | name | Age | cost | prerequisites | concept |", "|---|---|---|---|---|---|---|"]
    for n in macros:
        L.append(f"| {n['key']} | `{n['id']}` | {esc(n['name'])} | {n['age']} | {cost_cell(n)} | {esc(n.get('prereq'))} | "
                 f"{esc((n.get('civic') or {}).get('concept'))} |")
    L += ["", "## 9. Micro-civics", ""]
    strand_of = {}
    for st in m.get("strands") or []:
        for i in (st.get("existing") or []) + (st.get("new") or []):
            strand_of[i] = st.get("name")
    L += ["| key | id | name | strand | Age | cost | prerequisites | owner · milestone |", "|---|---|---|---|---|---|---|---|"]
    for n in sorted([n for n in nodes if (n.get("civic") or {}).get("category") != "macro"],
                    key=lambda n: (strand_of.get(n["id"], "~"), kr.AGES.index(n["age"]), n["key"])):
        cap = n.get("capability") or {}
        L.append(f"| {n['key']} | `{n['id']}` | {esc(n['name'])} | {esc(strand_of.get(n['id']))} | {n['age']} | {cost_cell(n)} | "
                 f"{esc(n.get('prereq'))} | {esc(cap.get('realizationOwner'))} · {esc(cap.get('milestone'))} |")
    L += ["", "## 10. AI valuation approach", ""]
    ai = m.get("aiValuationApproach") or {}
    L += [f"{esc(ai.get('status'))}", ""] + [f"- {x}" for x in ai.get("lane") or []] + \
         ([f"- {esc(ai.get('fog'))}"] if ai.get("fog") else []) + [""]
    L += ["## 11. Milestone ownership", ""] + [f"- **{k}**: {esc(v)}" for k, v in (m.get("milestoneOwnership") or {}).items()] + [""]
    ra = m.get("relocationAnalysis") or {}
    L += ["## 12. Relocation candidates from Technology", "", f"**Verdict.** {esc(ra.get('verdict'))} {esc(ra.get('why'))}", ""]
    for k, v in (ra.get("candidates") or {}).items():
        L.append(f"- `{k}`: {esc(v)}")
    L += ["", "## 13. Candidates considered and rejected", ""] + _tbl(m.get("rejectedCandidates") or [], ["id", "reason"]) + [""]
    L += ["## 14. Civilization VI — lessons only", ""] + [f"- {x}" for x in m.get("civVILessons") or []] + [""]
    L += ["## 15. Risks", ""] + _tbl(m.get("risks") or [], ["id", "risk", "mitigation"]) + [""]
    L += ["## 16. Open decisions", ""] + _tbl(m.get("openDecisions") or [], ["id", "question", "options", "recommendation"]) + [""]
    he = m.get("historicalEvidence") or {}
    L += ["## 17. Historical evidence status", "", f"{esc(he.get('status'))} {esc(he.get('handling'))}", "",
          "Educational texts and their sources for every civic are in the corpus (`educational-content-corpus.md`).", ""]
    write(kr.PKG / "civics-tree-proposal.md", [x for x in L if x is not None])


def render_corpus(tech, civ, corpus, reg):
    idx = kr.load_json(kr.PKG / "corpus" / "index.json") if (kr.PKG / "corpus" / "index.json").exists() else {"files": []}
    names = {n["id"]: n for n in tech["nodes"] + civ["nodes"]}
    out = []
    for f in idx.get("files", []):
        entries = [e for e in corpus.values() if e["_file"] == f["file"]]
        entries.sort(key=lambda e: names.get(e["id"], {}).get("key", 0))
        md = f["file"].replace(".json", ".md")
        out.append((f, md, len(entries)))
        L = [f"# Educational corpus — {f.get('title', f['file'])}", "", GEN, "",
             "Original prose. Word counts are computed by the validator. Sources resolve in "
             "`historical-source-register.md`. A citation shows where a claim can be checked; the fact-check line "
             "records what was actually checked.", ""]
        for e in entries:
            n = names.get(e["id"], {})
            srcs = "; ".join(f"[{s['sourceId']}] " + ", ".join(s.get("claims") or [])[:160] for s in e.get("sources") or [])
            fc = e.get("factCheck") or {}
            L += [f"### {n.get('key', '?')} · {n.get('name', e['id'])} (`{e['id']}`)", "",
                  e.get("description") or "", "",
                  f"- words: {kr.word_count(e.get('description'))} · fact-check: {fc.get('status', '—')} "
                  f"({esc(fc.get('checkedBy'))}; {esc(fc.get('method'))})",
                  f"- sources: {esc(srcs)}",
                  f"- uncertainty: {esc(e.get('uncertainty'))}",
                  f"- relation to mechanics: {esc(e.get('mechanicLink'))}", ""]
        write(kr.PKG / "corpus" / md, L)
    return out


def render_register(reg):
    rows = sorted(reg.values(), key=lambda s: s["id"])
    L = ["# Historical and comparative source register", "", GEN, "",
         f"{len(rows)} sources. Types: " + ", ".join(f"{k} {v}" for k, v in sorted(Counter(s.get('type') for s in rows).items())) + ".",
         "", "A source listed here was retrieved by the lane that cites it on the access date shown. Listing a source does "
         "not mean every claim attributed to it was independently verified — see each corpus entry's fact-check line "
         "and `educational-content-corpus.md` §3.", "",
         "| id | title | author / organization | published | type | confidence | URL | accessed | used by | notes |",
         "|---|---|---|---|---|---|---|---|---|---|"]
    for s in rows:
        used = s.get("usedBy") or []
        L.append("| " + " | ".join([s["id"], esc(s.get("title")), esc(s.get("author_org")), esc(s.get("published")),
                                    esc(s.get("type")), esc(s.get("confidence")), esc(s.get("url")),
                                    esc(s.get("accessed")),
                                    esc(", ".join(used[:6]) + (f" (+{len(used) - 6})" if len(used) > 6 else "")) if used else "—",
                                    esc(s.get("notes"))]) + " |")
    write(kr.PKG / "historical-source-register.md", L)


def main():
    tech, civ, inv, corpus, reg = load()
    a = render_current_audit(tech, civ, inv)
    p = render_proposal(tech, civ, corpus)
    m = render_matrix(tech, civ)
    render_civics(civ)
    if civ.get("civicsMeta"):
        render_civics_overview(civ)
    c = render_corpus(tech, civ, corpus, reg) if corpus else []
    if reg:
        render_register(reg)
    index = ["# Generated views — index", "", GEN, ""]
    index += ["## Current-tree inventory (MEASURED + proposed dispositions)", ""] + \
             [f"- [{BRANCH_TITLE.get(br, 'Civics')}]({name}) — {k} nodes" for br, name, k in a] + [""]
    index += ["## Proposed technology graph", ""] + \
             [f"- [{BRANCH_TITLE[br]}]({name}) — {k} records" for br, name, k in p] + \
             ["- [Civics detail](proposal/civics-detail.md)", ""]
    index += ["## Capability–dependency matrix", ""] + \
             [f"- [{BRANCH_TITLE.get(br, 'Civics')}]({name}) — {k} nodes" for br, name, k in m] + [""]
    if c:
        index += ["## Educational corpus", ""] + [f"- [{f.get('title', f['file'])}](corpus/{md}) — {k} entries" for f, md, k in c]
    write(kr.PKG / "generated-index.md", index)
    print("rendered:", len(a), "inventory files,", len(p), "proposal files,", len(m), "matrix files,", len(c), "corpus files")


if __name__ == "__main__":
    main()
